export function memoryConditionalStore() {
  const map=new Map(); const key=(id,phase)=>`${id}:${phase}`;
  return {map,
    readOperation:(id,phase)=>structuredClone(map.get(key(id,phase))||null),
    writeOperation:(id,phase,value)=>{const k=key(id,phase);if(map.has(k)){assert.deepEqual(map.get(k),value);return false;}map.set(k,structuredClone(value));return true;},
    claimOperation:(id,phase,value)=>{const k=key(id,phase);assert.ok(!map.has(k),'Conditional claim conflict');map.set(k,structuredClone(value));return true;},
  };
}

